import { type ReactNode } from 'react';

type TagVariant = 'ghost' | 'filled' | 'outlined';
type TagIntent = 'success' | 'warning' | 'danger' | 'info' | 'neutral' | 'brand' | 'ai' | 'disabled';
type TagSize = 'xs' | 's' | 'm';

export type TagProps = {
  variant?: TagVariant;
  intent?: TagIntent;
  size?: TagSize;
  dot?: boolean;
  icon?: ReactNode;
  avatar?: string;
  children: string;
  className?: string;
};

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export function Tag({
  variant = 'filled',
  intent = 'neutral',
  size = 's',
  dot = false,
  icon,
  avatar,
  children,
  className,
}: TagProps) {
  const classes = cn(
    'tag',
    `tag--${variant}`,
    `tag--${intent}`,
    `tag--${size}`,
    className,
  );

  return (
    <span className={classes}>
      {dot && <span className="tag__dot" />}
      {avatar && (
        <span className="tag__avatar">
          <img src={avatar} alt="" />
        </span>
      )}
      {icon && <span className="tag__icon">{icon}</span>}
      <span className="tag__label">{children}</span>
    </span>
  );
}

/* -------------------------------------------------------------------------
   Tag

   Status pill for categories, labels, and section headings.
   Pill shape (border-radius: 1000px). Non-interactive.

   Variants: ghost (no bg), filled (bg), outlined (border)
   Intents:  success, warning, danger, info, neutral, brand, ai, disabled
   Sizes:    xs (16px), s (20px), m (24px)
   Features: hasDots, hasIcon, hasAvatar
   ------------------------------------------------------------------------- */

.tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-1);
  max-width: 12.5rem;
  border-radius: var(--radius-full);
  border: var(--stroke-thin) solid transparent;
  font-family: var(--font-family-sans);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ---- Sizes ---- */

.tag--xs { height: 1rem; padding: 0 var(--spacing-2); font-size: var(--font-size-xs); }
.tag--s  { height: 1.25rem; padding: 0 var(--spacing-2); font-size: var(--font-size-xs); }
.tag--m  { height: 1.5rem; padding: 0 var(--spacing-2); font-size: var(--font-size-sm); }

/* ---- Ghost (text only, no bg) ---- */

.tag--ghost.tag--success   { color: var(--color-forest); }
.tag--ghost.tag--warning   { color: var(--color-amber-700); }
.tag--ghost.tag--danger    { color: var(--color-coral-700); }
.tag--ghost.tag--info      { color: var(--color-sky); }
.tag--ghost.tag--neutral   { color: var(--foreground); }
.tag--ghost.tag--brand     { color: var(--color-orange-700); }
.tag--ghost.tag--ai        { color: var(--color-green-electric); }
.tag--ghost.tag--disabled  { color: var(--muted-foreground); }

/* ---- Filled (bg + text) ---- */

.tag--filled.tag--success   {
  background-color: color-mix(in srgb, var(--color-green-electric) 18%, var(--background));
  color: var(--color-forest);
}
.tag--filled.tag--warning   { background-color: var(--color-amber-50); color: var(--color-amber-700); }
.tag--filled.tag--danger    {
  background-color: color-mix(in srgb, var(--color-coral-500) 16%, var(--background));
  color: var(--color-coral-700);
}
.tag--filled.tag--info      {
  background-color: color-mix(in srgb, var(--color-sky) 18%, var(--background));
  color: var(--color-neutral-900);
}
.tag--filled.tag--neutral   { background-color: var(--color-neutral-200); color: var(--foreground); }
.tag--filled.tag--brand     { background-color: var(--color-orange-50); color: var(--color-orange-700); }
.tag--filled.tag--ai        {
  background: linear-gradient(
    136deg,
    color-mix(in srgb, var(--color-green-electric) 20%, var(--background)),
    color-mix(in srgb, var(--color-forest) 12%, var(--background))
  );
  color: var(--color-forest);
}
.tag--filled.tag--disabled  { background-color: var(--muted); color: var(--muted-foreground); }

/* ---- Outlined (border + text) ---- */

.tag--outlined.tag--success   { border-color: var(--color-forest); color: var(--color-forest); }
.tag--outlined.tag--warning   { border-color: var(--color-amber-700); color: var(--color-amber-700); }
.tag--outlined.tag--danger    { border-color: var(--color-coral-700); color: var(--color-coral-700); }
.tag--outlined.tag--info      { border-color: var(--color-sky); color: var(--color-neutral-900); }
.tag--outlined.tag--neutral   { border-color: var(--border); color: var(--foreground); }
.tag--outlined.tag--brand     { border-color: var(--color-orange-700); color: var(--color-orange-700); }
.tag--outlined.tag--ai        { border-color: var(--color-green-electric); color: var(--color-forest); }
.tag--outlined.tag--disabled  { border-color: var(--muted); color: var(--muted-foreground); }

/* ---- Parts ---- */

.tag__dot {
  width: 0.375rem;
  height: 0.375rem;
  border-radius: var(--radius-full);
  background-color: currentColor;
  flex-shrink: 0;
}

.tag__icon {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.tag__avatar {
  flex-shrink: 0;
}

.tag__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 1px;
}
